#include <functional>
#include <iostream>
#include <map>
#include <string>
#include <vector>

struct DamageEvent
{
    int amount{};
    bool cancelled{};
};

std::map<std::string, std::vector<std::function<void(DamageEvent&)>>> g_before{};

void applyDamage(int& hp, int amount)
{
    DamageEvent e{amount};
    hp -= e.amount;
}

int main()
{
    int hp{20};
    applyDamage(hp, 10);
    std::cout << hp << '\n';
}
